"use client"

import * as React from "react"

const artwork = "data:image/avif;base64,"

// Only the eye band of the closed-eye frame is ever shown, so only that band ships.
const closedArtwork = "data:image/avif;base64,"
const CLOSED_STRIP = { x: 170, y: 505, width: 1330, height: 330 }

const CSS =
  ".pg-scene{--pg-x:0;--pg-y:0;position:relative;isolation:isolate;width:100%;aspect-ratio:16/9;overflow:hidden;background:#080707;color:var(--pg-accent)}" +
  ".pg-art{display:block;position:absolute;inset:-1%;width:102%;height:102%;max-width:none;object-fit:cover;transform:translate(calc(var(--pg-x)*-6px),calc(var(--pg-y)*-4px));transition:transform .35s ease-out;pointer-events:none;user-select:none}" +
  ".pg-light{position:absolute;inset:0;background:radial-gradient(ellipse at calc(50% + var(--pg-x)*35%) calc(50% + var(--pg-y)*35%),#fff0dd18,transparent 55%);mix-blend-mode:screen;pointer-events:none}" +
  ".pg-hit{position:absolute;inset:0;width:100%;height:100%;padding:0;border:0;border-radius:0;background:transparent;color:inherit;cursor:crosshair;touch-action:manipulation;-webkit-tap-highlight-color:transparent}" +
  ".pg-hit:focus-visible{outline:3px solid var(--pg-accent);outline-offset:-7px}" +
  ".pg-glints{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;transform:translate(calc(var(--pg-x)*3px),calc(var(--pg-y)*2px));transition:transform .35s ease-out}" +
  ".pg-star{fill:#fff4cf;opacity:.55;transform-box:fill-box;transform-origin:center;transition:opacity .25s,filter .25s}" +
  ".pg-scene:has(.pg-hit:hover) .pg-star,.pg-scene:has(.pg-hit:focus-visible) .pg-star,.pg-scene[data-active=true] .pg-star{opacity:1;filter:drop-shadow(0 0 5px #ffe9a6)}" +
  ".pg-hint{position:absolute;bottom:5%;left:50%;transform:translate(-50%,5px);padding:8px 15px;border:1px solid #f8c9df40;border-radius:30px;background:#130d13c9;color:#fbe6ed;font:12px/1.3 Georgia,serif;letter-spacing:.03em;white-space:nowrap;opacity:0;transition:opacity .25s,transform .25s;pointer-events:none}" +
  ".pg-hit:hover .pg-hint,.pg-hit:focus-visible .pg-hint{opacity:1;transform:translate(-50%,0)}" +
  ".pg-burst{position:absolute;inset:0;pointer-events:none}" +
  ".pg-particle{position:absolute;left:var(--pg-left);top:var(--pg-top);width:clamp(8px,1.4vw,18px);height:clamp(8px,1.4vw,18px);background:var(--pg-accent);clip-path:polygon(50% 0,62% 36%,100% 50%,62% 62%,50% 100%,36% 62%,0 50%,36% 36%);animation:pg-scatter 1.15s cubic-bezier(.16,.65,.25,1) both}" +
  ".pg-error{position:absolute;inset:0;display:grid;place-content:center;gap:12px;text-align:center;font:16px/1.5 Georgia,serif;padding:24px;background:#160f14}" +
  ".pg-retry{justify-self:center;color:inherit;background:transparent;border:1px solid currentColor;border-radius:30px;padding:8px 18px;font:inherit;cursor:pointer}" +
  ".pg-retry:focus-visible{outline:2px solid currentColor;outline-offset:4px}" +
  ".pg-eyelids{animation:pg-blink-frame .7s linear both}" +
  ".pg-scene[data-blinking=true] .pg-glints{visibility:hidden}" +
  "@keyframes pg-blink-frame{0%,100%{opacity:0}10%,88%{opacity:1}}" +
  "@keyframes pg-scatter{0%{opacity:0;transform:translate(-50%,-50%) scale(.2)}15%{opacity:1}100%{opacity:0;transform:translate(calc(-50% + var(--pg-dx)),calc(-50% + var(--pg-dy))) rotate(100deg) scale(.5)}}" +
  "@media(prefers-reduced-motion:reduce){.pg-scene .pg-art,.pg-scene .pg-glints{transform:none;transition:none}.pg-scene .pg-hint{transition:none}.pg-particle{animation:none;display:none}.pg-light,.pg-eyelids{display:none}}"

export interface PastelGazeProps {
  /** Replace the embedded pastel illustration with your own artwork. */
  src?: string
  /** Matching closed-eye frame, aligned to the same eye positions. */
  closedSrc?: string
  /** Occasional natural blinks, also triggered by activation. */
  blink?: boolean
  alt?: string
  accent?: string
  /** A definite CSS length; defaults to a responsive 16:9 scene. */
  height?: React.CSSProperties["height"]
  interactive?: boolean
  onActivate?: () => void
  className?: string
}

/** A little illustrated world. Move to catch the light; press to scatter stars. */
export default function PastelGaze({
  src = artwork,
  closedSrc,
  blink = true,
  alt = "Pastel portrait with starry hazel eyes, a pink butterfly, wildflowers and a crimson mushroom",
  accent = "#f8c9df",
  height = "auto",
  interactive = true,
  onActivate,
  className = "",
}: PastelGazeProps) {
  const scene = React.useRef(null as HTMLDivElement | null)
  const timer = React.useRef(undefined as ReturnType<typeof setTimeout> | undefined)
  const blinkTimer = React.useRef(undefined as ReturnType<typeof setTimeout> | undefined)
  const blinkLock = React.useRef(false)
  const hitBox = React.useRef(null as DOMRect | null)
  const maskId = React.useId().replace(/:/g, "")
  const [burst, setBurst] = React.useState(0)
  const [blinking, setBlinking] = React.useState(false)
  const [closedReady, setClosedReady] = React.useState(false)
  const [failed, setFailed] = React.useState(false)
  const [active, setActive] = React.useState(false)
  const closedFrame = closedSrc ?? (src === artwork ? closedArtwork : undefined)

  React.useEffect(() => () => { clearTimeout(timer.current); clearTimeout(blinkTimer.current) }, [])
  React.useEffect(() => setFailed(false), [src])

  React.useEffect(() => {
    const stale = () => { hitBox.current = null }
    addEventListener("scroll", stale, { passive: true })
    addEventListener("resize", stale)
    return () => { removeEventListener("scroll", stale); removeEventListener("resize", stale) }
  }, [])

  React.useEffect(() => {
    setClosedReady(false)
    setBlinking(false)
    blinkLock.current = false
    clearTimeout(blinkTimer.current)
    if (!closedFrame || !blink || !interactive) return
    const image = new Image()
    image.onload = () => setClosedReady(true)
    image.src = closedFrame
    return () => { image.onload = null }
  }, [closedFrame, blink, interactive])

  const closeEyes = React.useCallback(() => {
    if (!blink || !interactive || !closedReady || blinkLock.current || failed ||
      document.hidden || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    blinkLock.current = true
    setBlinking(true)
    blinkTimer.current = setTimeout(() => {
      setBlinking(false)
      blinkLock.current = false
    }, 720)
  }, [blink, interactive, closedReady, failed])

  React.useEffect(() => {
    if (!closedReady || !blink || !interactive) return
    let next: ReturnType<typeof setTimeout>
    const schedule = () => {
      next = setTimeout(() => {
        const box = scene.current?.getBoundingClientRect()
        if (box && box.bottom > 0 && box.top < window.innerHeight) closeEyes()
        schedule()
      }, 4200 + Math.random() * 2600)
    }
    schedule()
    return () => clearTimeout(next)
  }, [closedReady, blink, interactive, closeEyes])

  function reset() {
    scene.current?.style.setProperty("--pg-x", "0")
    scene.current?.style.setProperty("--pg-y", "0")
  }

  function move(event: React.PointerEvent<HTMLButtonElement>) {
    if (event.pointerType === "touch") return
    // measured once per enter (or after scroll/resize), never every move
    const box = hitBox.current ?? (hitBox.current = event.currentTarget.getBoundingClientRect())
    scene.current?.style.setProperty("--pg-x", String((event.clientX - box.left) / box.width - 0.5))
    scene.current?.style.setProperty("--pg-y", String((event.clientY - box.top) / box.height - 0.5))
  }

  function activate() {
    closeEyes()
    clearTimeout(timer.current)
    setBurst(value => value + 1)
    setActive(true)
    timer.current = setTimeout(() => setActive(false), 1200)
    onActivate?.()
  }

  return (
    <div ref={scene} className={"pg-scene " + className} style={{ height, "--pg-accent": accent } as React.CSSProperties} data-active={active} data-blinking={blinking}>
      <style>{CSS}</style>
      <img key={src + String(failed)} className="pg-art" src={src} alt={alt} width={1672} height={941} draggable={false} onError={() => setFailed(true)} />
      {blinking && closedFrame && <svg className="pg-art pg-eyelids" viewBox="0 0 1672 941" preserveAspectRatio="xMidYMid slice" width={1672} height={941} aria-hidden="true">
        <defs>
          <radialGradient id={maskId + "-feather"}>
            <stop offset="75%" stopColor="white" />
            <stop offset="100%" stopColor="black" />
          </radialGradient>
          <mask id={maskId + "-patch"} maskUnits="userSpaceOnUse" x="0" y="0" width="1672" height="941">
            <ellipse cx="470" cy="670" rx="300" ry="160" fill={"url(#" + maskId + "-feather)"} />
            <ellipse cx="1200" cy="665" rx="300" ry="165" fill={"url(#" + maskId + "-feather)"} />
          </mask>
          <clipPath id={maskId + "-opening"}>
            {[
              ["M200 625 C360 520 575 520 725 725 C555 820 345 800 200 625Z", "M200 685 C355 760 535 785 725 718 C535 785 355 760 200 685Z"],
              ["M980 725 C1135 515 1360 505 1480 610 C1370 805 1135 815 980 725Z", "M980 720 C1130 700 1295 810 1480 680 C1295 810 1130 700 980 720Z"],
            ].map(([open, closed], index) => <path key={index} d={open}>
              <animate attributeName="d" values={[open, closed, closed, open].join(";")} keyTimes="0;0.28;0.48;1" dur="0.7s" begin="0s" fill="freeze" calcMode="spline" keySplines=".3 0 .6 1;0 0 1 1;.2 0 .3 1" />
            </path>)}
          </clipPath>
        </defs>
        <g mask={"url(#" + maskId + "-patch)"}>
          {closedFrame === closedArtwork
            ? <image href={closedFrame} x={CLOSED_STRIP.x} y={CLOSED_STRIP.y} width={CLOSED_STRIP.width} height={CLOSED_STRIP.height} preserveAspectRatio="none" />
            : <image href={closedFrame} width="1672" height="941" preserveAspectRatio="none" />}
          <image href={src} width="1672" height="941" preserveAspectRatio="none" clipPath={"url(#" + maskId + "-opening)"} />
        </g>
      </svg>}
      <div className="pg-light" aria-hidden="true" />
      {interactive && !failed && <>
        <svg className="pg-glints" viewBox="0 0 1000 562.5" aria-hidden="true">
          {[{ x: 316, y: 382 }, { x: 710, y: 379 }].map(({ x, y }) => (
            <path key={x} className="pg-star" d={"M" + x + " " + (y - 7) + "l2 5 6 2-6 2-2 6-2-6-5-2 5-2Z"} />
          ))}
        </svg>
        <button type="button" className="pg-hit" aria-label={blink ? "Blink and scatter stars across the illustration" : "Scatter stars across the illustration"} onPointerEnter={() => { hitBox.current = null }} onPointerMove={move} onPointerLeave={reset} onBlur={reset} onClick={activate}>
          <span className="pg-hint" aria-hidden="true">{active ? "A little everyday magic" : "Touch a little magic"}</span>
        </button>
        {active && <div key={burst} className="pg-burst" aria-hidden="true">
          {Array.from({ length: 24 }, (_, index) => {
            const angle = (index % 12) / 12 * Math.PI * 2
            return <span key={index} className="pg-particle" style={{
              "--pg-left": index < 12 ? "31.6%" : "71%",
              "--pg-top": "68%",
              "--pg-dx": Math.cos(angle) * (65 + index % 3 * 25) + "px",
              "--pg-dy": Math.sin(angle) * (65 + index % 3 * 25) + "px",
            } as React.CSSProperties} />
          })}
        </div>}
      </>}
      {failed && <div className="pg-error" role="alert">
        <span>The illustration couldn’t load.</span>
        <button type="button" className="pg-retry" onClick={() => setFailed(false)}>Try again</button>
      </div>}
    </div>
  )
}

